import{_ as r,l as n,o as t,c as s,v as e,p as l,x as o,d as E,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"多期消费组合","description":"","frontmatter":{"title":"多期消费组合","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/multi-period-consumption-portfolio.md","filePath":"econ/multi-period-consumption-portfolio.md","lastUpdated":1789023840000}'),c={name:"econ/multi-period-consumption-portfolio.md"};function d(A,a,B,h,_,u){const i=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="多期消费组合" tabindex="-1">多期消费组合 <a class="header-anchor" href="#多期消费组合" aria-label="Permalink to &quot;多期消费组合&quot;">​</a></h1><div class="epigraph"><p>离散多期里，消费与组合仍由欧拉与两基金（机会确定时）给出；连续时间 Merton 是这一结构的扩散极限，不是另一套偏好。</p><footer>—— Samuelson, Lifetime Portfolio Selection by Dynamic Stochastic Programming, Review of Economics and Statistics, 1969；对照 Merton 1969/1971</footer></div><p><a href="/econ/transaction-cost-portfolio-theory">上一课</a>在连续时间里因成本把点政策改成区间。本课缺口是把消费–组合收回到<strong>离散多期</strong>，与 Samuelson（1969）对齐，并作为本单元、本课程的收束：后课若进入动态宏观，默认已经有欧拉、两基金、对冲、以及摩擦何时破坏它们。不重解 HJB，不重写需求系统。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Samuelson：有限生命、离散期、独立同分布回报（机会确定），CRRA 或对数下每期组合权重与剩余寿命无关（短视），消费率随剩余寿命变。这与 Merton 常机会的常数 \\(\\theta\\)、变 \\(c/W\\) 同构，只是时间装置不同。机会若 Markov，离散贝尔曼同样出现对冲项——ICAPM 不必非连续不可。缺口是钉：本单元不是「只有连续时间才有组合理论」；连续时间的贡献是瞬时 MV 许可证与随机积分复制，离散已经有欧拉与动态规划。</p><p>与 <a href="/econ/consumption-euler">跨期欧拉</a>：资产菜单一旦超过债券，欧拉对每个可交易回报成立，\\(m\\) 仍是 \\(\\beta u&#39;(c_{t+1})/u&#39;(c_t)\\)。组合一阶是欧拉的资产形式。本课把菜单写回来。</p><p><span class="marginnote">Samuelson, <em>REStat</em> 51(3), 1969。与 Merton 同年连续时间互为对照。Hakansson 等在离散里写过类似短视结果。CRRA 加 iid 是短视的标准许可证。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>贝尔曼 \\(V_t(W)=\\max_{c,\\theta} u(c)+\\beta\\mathrm{E}[V_{t+1}(W&#39;)]\\)，\\(W&#39;=(W-c)R_p(\\theta)\\)。一阶：\\(u&#39;(c)=\\beta\\mathrm{E}[V_{t+1}&#39;(W&#39;)R_p]\\)，以及 \\(\\theta\\) 使 \\(\\mathrm{E}[V_{t+1}&#39;(W&#39;)(R_i-R_f)]=0\\)。CRRA 加 iid：\\(V\\) 幂形式，\\(\\theta\\) 与 \\(t\\) 无关。Markov 状态 \\(z\\)：\\(V_t(W,z)\\)，对冲出现。交易成本：离散也能写 \\(sS\\)；连续极限把 \\(sS\\) 变成 Constantinides 带。不完全：欧拉只对可交易 \\(R_i\\) 成立，不可交易收入进预算但不进菜单。</p>',9)),(t(),l(p,null,{default:o(()=>[m(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SAM%5B%22Samuelson%20%E7%A6%BB%E6%95%A3%22%5D%20--%3E%20MY%5B%22iid%20%2B%20CRRA%3A%20%E7%9F%AD%E8%A7%86%20%CE%B8%22%5D%0A%20%20MER%5B%22Merton%20%E8%BF%9E%E7%BB%AD%22%5D%20--%3E%20MY2%5B%22%E5%B8%B8%E6%9C%BA%E4%BC%9A%3A%20%E5%B8%B8%E6%95%B0%20%CE%B8%22%5D%0A%20%20MY%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%E7%BB%93%E6%9E%84%2C%20%E8%A3%85%E7%BD%AE%E4%B8%8D%E5%90%8C%22%5D%0A%20%20MY2%20--%3E%20SAME%0A%20%20Z%5B%22%E6%9C%BA%E4%BC%9A%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20HD%5B%22%E4%B8%A4%E8%BE%B9%E9%83%BD%E6%9C%89%E5%AF%B9%E5%86%B2%22%5D%0A%20%20FRI%5B%22%E6%88%90%E6%9C%AC%20%2F%20%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20BRK%5B%22%E7%9F%AD%E8%A7%86%E4%B8%8E%E4%B8%A4%E5%9F%BA%E9%87%91%E7%A0%B4%E5%9D%8F%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>本课程从 Grossman–Stiglitz 走到这里：信息决定价格作为信号；FTAP 给出 \\(m\\)；摩擦改谁的 \\(m\\)；连续与离散给出组合如何持有。下一课程若是动态宏观，求解装置（贝尔曼、欧拉）从这里交接，不再从零讲组合。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是动态规划的包络。无论离散还是连续，财富的影子价格连接消费与投资。短视来自「未来值函数对组合的依赖只通过财富标度」——CRRA 加 iid 保证标度。破坏标度的东西（习惯、劳动收入、约束、成本、随机机会）都引入额外状态，从而引入对冲或惰性。信息：若 \\(z\\) 含私人信号，个人域流不同，加总不再是共同切点——回到本课程第一课序，而不是再写一遍 REE。</p><p>与 <a href="/econ/to-limit-order-book">到限价簿</a>：多期组合给出想持有的 \\(\\theta\\)；簿给出如何把 \\(\\theta\\) 变成成交。本课仍不停在协议上。理论课程在组合政策处可以停，执行换栏。</p><p><span class="marginnote">无限生命离散 CRRA iid 与 Merton 无限生命同样平稳。有限生命只改消费路径的倾斜，不改短视权重——这是教学上常被忽略的 Samuelson 要点。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是家庭金融实证（参与之谜已在上一课程）。不估计寿险需求。作为「信息、流动性与资产定价理论续」的最后一课：不把附录论文插入其后。若继续，动态宏观补层从贝尔曼求解起，或回到量化栏看执行与因子。</p><p>后课默认（本课程结束）：离散与连续的消费–组合同构；短视需要 CRRA+iid；对冲、成本、约束、私人信息都会破坏两基金加总。\\(m\\) 仍是欧拉；FTAP 仍是无套利；价格作为信号仍是 REE。限价簿仍是协议。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Samuelson 离散与 Merton 连续：常机会下短视组合、消费摊平财富。</li><li>额外状态（机会、习惯、收入、成本、约束）引入对冲或惰性。</li><li>本课程在此收束：信息核、无套利核、摩擦核、组合核已经对齐；\\(p\\) 的协议不在本栏。</li><li>出处：Samuelson, <em>REStat</em> 1969；Merton, <em>REStat</em> 1969、<em>JET</em> 1971。</li></ul>',10))])}const S=r(c,[["render",d]]);export{R as __pageData,S as default};
